-- Remover políticas de escrita do admin via anon key (após migração completa)
DROP POLICY IF EXISTS "connectors_admin_all"    ON public.channel_connectors;
DROP POLICY IF EXISTS "businesses_admin_all"    ON public.monitored_businesses;
DROP POLICY IF EXISTS "tenants_admin_all"       ON public.tenants;
DROP POLICY IF EXISTS "tenant_users_admin_all"  ON public.tenant_users;
DROP POLICY IF EXISTS "alert_events_admin_all"  ON public.alert_events;
DROP POLICY IF EXISTS "reviews_admin_all"       ON public.reviews;

-- Manter apenas as políticas de SELECT para superadmin (leitura no admin panel)
-- As políticas de SELECT já existem do script fix-portal-rls.sql e fix-admin-write-rls.sql
-- Verificar estado final:
SELECT tablename, policyname, cmd FROM pg_policies
WHERE schemaname = 'public'
ORDER BY tablename, policyname;

endpoint.code:
async function handleCreateConnector(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req) as {
    business_id: string
    channel: string
    external_id: string
    config?: Record<string, unknown>
  }
  const { data, error } = await supabaseAdmin
    .from('channel_connectors')
    .insert({
      business_id: body.business_id,
      channel: body.channel,
      external_id: body.external_id,
      status: 'active',
      config: body.config ?? { interval_minutes: 60 },
    })
    .select()
    .single()
  if (error) {
    res.writeHead(400, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: error.message }))
    return
  }
  res.writeHead(201, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify(data))
}

async function handleUpdateConnectorConfig(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const connectorId = req.url?.split('/api/admin/connector/')[1]?.split('/config')[0]
  const body = await readBody(req) as {
    config: Record<string, unknown>
    external_id: string
    status: string
  }
  const { error } = await supabaseAdmin
    .from('channel_connectors')
    .update({
      config: body.config,
      external_id: body.external_id,
      status: body.status ?? 'active',
    })
    .eq('id', connectorId)
  if (error) {
    res.writeHead(400, { 'Content-Type': 'application/json' })
    res.end(JSON.stringify({ error: error.message }))
    return
  }
  res.writeHead(200, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify({ ok: true }))
}

async function handleUpdateTenant(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const tenantId = req.url?.split('/api/admin/tenant/')[1]?.split('?')[0]
  const body = await readBody(req) as {
    name?: string
    cnpj?: string
    plan?: string
    business_name?: string
    business_cnpj?: string
    business_category?: string
  }

  // Atualizar tenant
  if (body.name || body.plan) {
    const { error } = await supabaseAdmin
      .from('tenants')
      .update({
        ...(body.name  ? { name: body.name }   : {}),
        ...(body.plan  ? { plan: body.plan }    : {}),
      })
      .eq('id', tenantId)
    if (error) {
      res.writeHead(400, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ error: error.message }))
      return
    }
  }

  // Atualizar business associada (se campos fornecidos)
  if (body.business_name || body.business_cnpj || body.business_category) {
    const updates: Record<string, unknown> = {}
    if (body.business_name)     updates['name']     = body.business_name
    if (body.business_cnpj)     updates['cnpj']     = body.business_cnpj
    if (body.business_category) updates['category'] = body.business_category

    const { error } = await supabaseAdmin
      .from('monitored_businesses')
      .update(updates)
      .eq('tenant_id', tenantId)
    if (error) {
      res.writeHead(400, { 'Content-Type': 'application/json' })
      res.end(JSON.stringify({ error: error.message }))
      return
    }
  }

  res.writeHead(200, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify({ ok: true }))
}

async function handleToggleTenantActive(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const tenantId = req.url?.split('/api/admin/tenant/')[1]?.split('/active')[0]
  const body = await readBody(req) as { is_active: boolean }

  await Promise.all([
    supabaseAdmin.from('tenants').update({ is_active: body.is_active }).eq('id', tenantId),
    supabaseAdmin.from('monitored_businesses').update({ is_active: body.is_active }).eq('tenant_id', tenantId),
  ])

  res.writeHead(200, { 'Content-Type': 'application/json' })
  res.end(JSON.stringify({ ok: true }))
}

router_additions.code:
// --- Novas rotas admin ---
if (method === 'POST'  && path === '/api/admin/connector')                    return handleCreateConnector(req, res)
if (method === 'PATCH' && path.match(/^\/api\/admin\/connector\/[^/]+\/config$/))  return handleUpdateConnectorConfig(req, res)
if (method === 'PATCH' && path.match(/^\/api\/admin\/connector\/[^/]+\/force-sync$/)) return handleForceSync(req, res)
if (method === 'PATCH' && path.match(/^\/api\/admin\/tenant\/[^/]+$/) && !path.endsWith('/active')) return handleUpdateTenant(req, res)
if (method === 'PATCH' && path.match(/^\/api\/admin\/tenant\/[^/]+\/active$/)) return handleToggleTenantActive(req, res)

