async function updateConfig() {
  if (!selected) return
  let parsedConfig = selected.config || {}
  try {
    if (editingConfigJson.trim()) {
      parsedConfig = JSON.parse(editingConfigJson)
    }
  } catch {
    alert('Formato JSON inválido na Configuração Avançada.')
    return
  }
  const newConfig = { ...parsedConfig, interval_minutes: intervalMinutes }
  const apiUrl = import.meta.env.VITE_API_URL ?? 'https://reputei-api.railway.app'
  const resp = await fetch(`${apiUrl}/api/admin/connector/${selected.id}/config`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ config: newConfig, external_id: editingExternalId, status: 'active' }),
  })
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({ error: resp.statusText }))
    alert('Erro ao salvar: ' + (err.error ?? resp.statusText))
    return
  }
  setSelected({ ...selected, config: newConfig, external_id: editingExternalId, status: 'active' })
  setEditingConfig(false)
  loadAll()
}

function_change.current_code:
async function forceSync() {
  if (!selected) return
  const now = new Date().toISOString()
  await supabase.from('channel_connectors').update({
    next_sync_at: now,
    status: 'active'
  }).eq('id', selected.id)
  setSelected({ ...selected, next_sync_at: now, status: 'active' })
  loadAll()
}

function_change.new_code:
async function forceSync() {
  if (!selected) return
  const apiUrl = import.meta.env.VITE_API_URL ?? 'https://reputei-api.railway.app'
  await fetch(`${apiUrl}/api/admin/connector/${selected.id}/force-sync`, { method: 'PATCH' })
  const now = new Date().toISOString()
  setSelected({ ...selected, next_sync_at: now, status: 'active' })
  loadAll()
}

async function handleEditSave() {
  if (!editingTenant) return
  const apiUrl = import.meta.env.VITE_API_URL ?? 'https://reputei-api.railway.app'
  const resp = await fetch(`${apiUrl}/api/admin/tenant/${editingTenant.id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name: editForm.name,
      plan: editForm.plan,
      business_name: editForm.business_name,
      business_cnpj: editForm.business_cnpj,
      business_category: editForm.business_category,
    }),
  })
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({ error: resp.statusText }))
    alert('Erro: ' + (err.error ?? resp.statusText))
    return
  }
  setEditingTenant(null)
  loadAll()
  window.dispatchEvent(new Event('refresh_data'))
}

async function toggleActive(t: Tenant, newVal: boolean) {
  const apiUrl = import.meta.env.VITE_API_URL ?? 'https://reputei-api.railway.app'
  await fetch(`${apiUrl}/api/admin/tenant/${t.id}/active`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ is_active: newVal }),
  })
  loadAll()
}

async function handleBusinessUpdate(tenantId: string) {
  const apiUrl = import.meta.env.VITE_API_URL ?? 'https://reputei-api.railway.app'
  const resp = await fetch(`${apiUrl}/api/admin/tenant/${tenantId}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      business_name: businessForm.name,
      business_cnpj: businessForm.cnpj,
      business_category: businessForm.category,
    }),
  })
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({ error: resp.statusText }))
    alert('Erro: ' + (err.error ?? resp.statusText))
    return
  }
  setEditingBusiness(null)
  loadAll()
}
